# -*- coding: utf-8 -*-
from pathlib import Path
import subprocess
import yaml

p=Path('projects/stezhok')
l=p/'state/ledger'
def read(name): return yaml.safe_load((l/name).read_text())
def save(name, rows):
    (l/name).write_text(yaml.safe_dump(rows,allow_unicode=True,sort_keys=False))
    subprocess.run(['.venv/bin/python','tools/ledger.py','validate',str(p)],check=True)

response=Path('../inputs/02-C2-synthetic.txt').read_text()
(p/'state/c2_revision_choice_synthetic.txt').write_text(response)
d=read('decisions.yaml')
d[0]['state']='decided'
d[0]['rationale']+='\n\nПовторный C2 по CHG-001, дословный синтетический ответ (не реальное согласие):\n'+response
d[0]['decided_at']='2026-11-19'
d[0]['decided_by']='Инициатор — СИНТЕТИЧЕСКИЙ УЧЕБНЫЙ СЦЕНАРИЙ, не реальное согласие'
d[0]['status_note']='CHG-001: повторный C2 явно сохраняет ALT-001 с готовым локальным CLI только для оформления вручную проверенных карточек и условным HYP-004. C3 открыт; потребительские обещания запрещены.'
save('decisions.yaml',d)

prm=dict(id='PRM-001', message='Получите Markdown-карточку из вручную заполненного примера в локальном CLI: на проверенном входе оформление выполнено. Истинность и пригодность текста проверяет аналитик.', audience='Синтетический внутренний аналитик/инициатор, после ручного заполнения карточки и до содержательного разбора; только локальный CLI и проверенный пример.', barrier='Заполненный документ можно ошибочно принять за проверенное обещание; отрицательный контроль CLM-009 показывает, что содержание не валидируется.', feature='Локальное оформление карточек в Markdown', proof=['CLM-008','CLM-009'],channels=['Локальный CLI и локальный Markdown; без публикации'],decision='DEC-001',status_note='CHG-001: активное сообщение только внутреннего учебного пакета, не потребительская коммуникация и не разрешение использования до C3. Проверенная поверхность — CLI, не сайт/приложение; истинность, полнота и полезность не обещаются.')
save('promises.yaml',[prm])

exps=read('experiments.yaml')
exps[0]['duration']='Один полный внутренний кабинетный проход после C3; окно — от начала сверки заданных классов до явного вердикта инициатора. Лимит активного труда 2 часа по HYP-004; это трудозатраты, не длительность наблюдения за жителями.'
exps[0]['effort']='Сценарно один синтетический аналитик, до 2 часов × 1000 рублей/час, до 2000 рублей труда; прямой доход 0 (HYP-004, CLM-010). Реальный бюджет не выделен, новых платных вызовов и контактов нет.'
exps[0]['stop_go']='Предложение к C3 по CHG-001, ещё не утверждено. Сначала stop: любое приписывание аналога Стежку, нарушение запрета, превышение 2 часов труда по HYP-004 либо явный ответ инициатора об отсутствии полезного изменения. Если stop не выполнен, go только когда все заданные классы CLM-006 имеют корректные источник, область, ограничение и следующее допустимое действие И инициатор явно подтвердил полезное изменение требования И труд не превышает 2 часа. Равенство лимиту допустимо; более лимита — stop. При отсутствии ответа/строк — недостаток данных: сохранить материал, запросить только недостающее, до go пауза. При конфликте stop важнее go. Серая зона: полный материал, но полезность неоднозначна — сохранить и вынести решение инициатору без новой работы. Go допускает лишь внутреннее обсуждение результата, не масштабирование, запуск или публикацию. Порог труда — независимый сценарный предел, не денежная безубыточность.'
exps[0]['owner']='Инициатор и аналитик — синтетические роли, реальные ресурсы не назначены'
exps[0]['status_note']='CHG-001: после отдельного синтетического C2 уточнены длительность/усилие и stop_go по HYP-004; это предложения к C3, EXP не исполнялся. CLI-прогон CLM-008/009 не измеряет полезность и не является результатом EXP-001.'
exps[1]['status_note']='CHG-001: HYP-003 относится только к будущей потребительской функции, остаётся открытой; текущий CLI её не подтверждает. EXP-002 отложен за предел текущего внутреннего пакета, не prerequisite PRM-001. Не исполнялся; порог не изменён. Возврат потребует разрешённого нового материала и нового согласования.'
save('experiments.yaml',exps)

econ=dict(name='Сценарный предел труда внутреннего кабинетного разбора, не коммерческий прогноз',decision='DEC-001',unit='рублей/разбор',formula='income - hours * rate',breakeven_var='hours',breakeven_target=0,drivers=[dict(id='hours',label='Сценарное активное время: нижняя граница без работы, base/high полный лимит',low=0,base=2,high=2,type='assumption',ref='HYP-004'),dict(id='rate',label='Условная оценка труда, не рыночная цена',low=1000,base=1000,high=1000,type='assumption',ref='HYP-004'),dict(id='income',label='Прямой доход, не оценка немонетарной полезности',low=0,base=0,high=0,type='assumption',ref='HYP-004')])
(p/'state/economics.yaml').write_text(yaml.safe_dump(econ,allow_unicode=True,sort_keys=False))
